#!/usr/bin/env node

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import process from "node:process";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const VERSION = "1.0.0";
const SCRIPT_DIR = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(SCRIPT_DIR, "..");
const DEFAULT_CATALOG = path.join(ROOT, "dev_scripts", "native-contract-catalog.json");
const DEFAULT_OUTPUT_ROOT = path.join(ROOT, "dev_scripts", "runtime-probes");
const STOPWORDS = new Set([
  "the", "and", "for", "with", "from", "through", "into", "that", "this",
  "frame", "conn", "lancer", "native", "runtime", "behavior", "action", "feature"
]);

function parseArgs(argv) {
  const args = { goal: null, id: null, corridor: null, runtimeMap: null, nativeRoot: null, catalog: DEFAULT_CATALOG, outputDir: null, jsonOnly: false, selfTest: false };
  for (let i = 2; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === "--goal") args.goal = argv[++i] ?? null;
    else if (arg === "--id") args.id = argv[++i] ?? null;
    else if (arg === "--corridor") args.corridor = path.resolve(argv[++i] ?? "");
    else if (arg === "--runtime-map") args.runtimeMap = path.resolve(argv[++i] ?? "");
    else if (arg === "--native-root") args.nativeRoot = path.resolve(argv[++i] ?? "");
    else if (arg === "--catalog") args.catalog = path.resolve(argv[++i] ?? DEFAULT_CATALOG);
    else if (arg === "--output-dir") args.outputDir = path.resolve(argv[++i] ?? DEFAULT_OUTPUT_ROOT);
    else if (arg === "--json-only") args.jsonOnly = true;
    else if (arg === "--self-test") args.selfTest = true;
    else if (arg === "--help" || arg === "-h") { printHelp(); process.exit(0); }
    else throw new Error(`Unknown argument: ${arg}`);
  }
  return args;
}

function printHelp() {
  console.log(`Frame Conn Runtime Contract Probes\n\n` +
    `Generate a live-test bundle:\n` +
    `  node dev_scripts/runtime-contract-probes.mjs --goal "Brace reaction reduces damage and restricts next turn"\n\n` +
    `Options:\n` +
    `  --goal <text>          Behavioral goal used to derive probe obligations\n` +
    `  --id <id>              Stable bundle id (derived from goal by default)\n` +
    `  --corridor <file>      Existing certified Patch Corridor report\n` +
    `  --runtime-map <file>   Existing Runtime Signal Map report\n` +
    `  --native-root <path>   Add authoritative native Lancer source to the generated signal map\n` +
    `  --catalog <file>       Native Contract Catalog JSON\n` +
    `  --output-dir <path>    Bundle directory\n` +
    `  --self-test            Run deterministic synthetic test\n`);
}

const slash = value => String(value).replaceAll("\\", "/");
const itemId = item => String(item?.id ?? "");
const stableId = value => String(value ?? "probe").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 72) || "probe";

function tokens(value) {
  return [...new Set(String(value ?? "").toLowerCase().split(/[^a-z0-9_$.-]+/).filter(token => token.length > 1 && !STOPWORDS.has(token)))];
}

function runNode(script, args, label) {
  if (!fs.existsSync(script)) throw new Error(`${label} not found: ${script}`);
  const result = spawnSync(process.execPath, [script, ...args], { cwd: ROOT, encoding: "utf8", maxBuffer: 16 * 1024 * 1024 });
  if (result.stdout) process.stdout.write(result.stdout);
  if (result.stderr) process.stderr.write(result.stderr);
  if (result.error) throw new Error(`${label} could not start: ${result.error}`);
  if (result.status !== 0) throw new Error(`${label} failed with exit code ${result.status}.`);
}

function loadCorridor(goal, corridorPath) {
  if (corridorPath) {
    const report = JSON.parse(fs.readFileSync(corridorPath, "utf8"));
    if (report.clauseCoverage?.complete !== true) throw new Error("Runtime probes require a clause-complete Patch Corridor.");
    return report;
  }
  const output = path.join(os.tmpdir(), `frame-conn-probe-corridor-${process.pid}.json`);
  runNode(path.join(ROOT, "dev_scripts", "patch-corridor-planner.mjs"), ["--goal", goal, "--output", output], "Patch Corridor");
  const report = JSON.parse(fs.readFileSync(output, "utf8"));
  if (report.clauseCoverage?.complete !== true) throw new Error("Runtime probes require a clause-complete Patch Corridor.");
  return report;
}

function loadRuntimeMap(runtimeMapPath, nativeRoot) {
  if (runtimeMapPath) return JSON.parse(fs.readFileSync(runtimeMapPath, "utf8"));
  const output = path.join(os.tmpdir(), `frame-conn-probe-runtime-map-${process.pid}.json`);
  const args = ["--output", output, "--json-only"];
  if (nativeRoot) args.push("--native-root", nativeRoot);
  runNode(path.join(ROOT, "dev_scripts", "runtime-signal-map.mjs"), args, "Runtime Signal Map");
  return JSON.parse(fs.readFileSync(output, "utf8"));
}

function loadCatalog(catalogPath) {
  if (!catalogPath || !fs.existsSync(catalogPath)) return { contracts: [], native_system: null };
  return JSON.parse(fs.readFileSync(catalogPath, "utf8"));
}

function clauseRecords(corridor) {
  return (corridor.clauses ?? []).map((clause, index) => ({
    id: clause.id ?? `clause-${index + 1}`,
    text: clause.text ?? String(clause),
    concerns: [...new Set([...(clause.concerns ?? []), ...((clause.obligations ?? []).map(item => item.concern).filter(Boolean))])],
    complete: clause.complete !== false
  }));
}

function searchableNode(node) {
  return [node.name, node.qualifiedName, node.kind, node.effectKind, node.file, node.selector, node.eventName, ...(node.tags ?? []), node.evidence].filter(Boolean).join(" \

operations:
presentation" && ["event", "hook", "effect"].includes(node.kind)) return 5;
  if ((concern === "hook/event" || concern === "hook") && ["hook", "event"].includes(node.kind)) return 6;
  if (concern === "native-execution" && ["flow", "flow-step", "effect", "callable"].includes(node.kind)) return 5;
  if (["state", "lifecycle", "transaction", "reaction", "action-economy", "movement"].includes(concern) && ["hook", "effect", "callable"].includes(node.kind)) return 3;
  return 0;
}

function scoreNode(node, clause) {
  const haystack = searchableNode(node);
  let score = tokens(clause.text).reduce((sum, term) => sum + (haystack.includes(term) ? 4 : 0), 0);
  for (const concern of clause.concerns) score += concernKindBonus(concern, node);
  if (node.source === "frame-conn") score += 1;
  if (node.kind === "effect") score += 1;
  return score;
}

function selectNodes(runtimeMap, clause, limit = 8) {
  return (runtimeMap.nodes ?? []).map(node => ({ node, score: scoreNode(node, clause) })).filter(item => item.score > 0).sort((a, b) => b.score - a.score || String(a.node.id).localeCompare(String(b.node.id))).slice(0, limit);
}

function contractText(contract) {
  return [contract.id, contract.title, contract.summary, contract.contract_kind, ...(contract.keywords ?? []), contract.boundary?.rule].filter(Boolean).join(" \

proven").map(contract => {
    const haystack = contractText(contract);
    return { contract, score: terms.reduce((sum, term) => sum + (haystack.includes(term) ? 4 : 0), 0) };
  }).filter(item => item.score > 0).sort((a, b) => b.score - a.score || itemId(a.contract).localeCompare(itemId(b.contract))).slice(0, limit);
}

function sourceEvidence(node) {
  return { nodeId: node.id ?? null, source: node.source ?? null, file: node.file ?? null, line: node.line ?? null, evidence: node.evidence ?? null };
}

function nodeProbe(node, clauseId) {
  if (node.kind === "flow" && node.name) return { id: `flow-${stableId(node.name)}`, clauseIds: [clauseId], kind: "flow-lifecycle", label: `Observe Flow lifecycle: ${node.name}`, flowName: node.name, evidence: sourceEvidence(node) };
  if (node.kind === "hook" && node.name) return { id: `hook-${stableId(node.name)}`, clauseIds: [clauseId], kind: "hook", label: `Observe hook: ${node.name}`, hookName: node.name, evidence: sourceEvidence(node) };
  if (node.kind === "event" && node.eventName) return { id: `event-${stableId(`${node.eventName}-${node.selector ?? node.name}`)}`, clauseIds: [clauseId], kind: "dom-event", label: `Observe ${node.eventName}${node.selector ? ` ${node.selector}` : ""}`, eventName: node.eventName, selector: node.selector ?? null, evidence: sourceEvidence(node) };
  if (node.kind === "effect" && String(node.name ?? "").endsWith("ChatMessage.create")) return { id: "effect-chat-message-create", clauseIds: [clauseId], kind: "global-method", label: "Observe ChatMessage.create", objectPath: "ChatMessage", methodName: "create", evidence: sourceEvidence(node) };
  return null;
}

function flowNamesFromContract(contract) {
  const names = new Set();
  for (const evidence of contract.evidence ?? []) {
    for (const name of String(evidence.symbol ?? "").match(/[A-Za-z_$][\w$]*Flow/g) ?? []) names.add(name);
  }
  for (const name of contractText(contract).match(/\b[A-Za-z_$][\w$]*Flow\b/g) ?? []) names.add(name);
  return [...names];
}

function mergeProbe(map, probe) {
  if (!probe) return;
  const current = map.get(probe.id);
  if (!current) { map.set(probe.id, probe); return; }
  current.clauseIds = [...new Set([...(current.clauseIds ?? []), ...(probe.clauseIds ?? [])])];
}

function deriveManifest(goal, id, corridor, runtimeMap, catalog) {
  const clauses = clauseRecords(corridor);
  if (!clauses.length) throw new Error("Certified corridor contains no clauses to probe.");
  const probeMap = new Map();
  const objectives = [];
  for (const clause of clauses) {
    const selectedNodes = selectNodes(runtimeMap, clause);
    const selectedContracts = selectContracts(catalog, clause);
    const relatedProbeIds = [];
    for (const { node } of selectedNodes) {
      const probe = nodeProbe(node, clause.id);
      if (!probe) continue;
      mergeProbe(probeMap, probe);
      relatedProbeIds.push(probe.id);
    }
    for (const { contract } of selectedContracts) {
      for (const flowName of flowNamesFromContract(contract)) {
        const probe = {
          id: `flow-${stableId(flowName)}`, clauseIds: [clause.id], kind: "flow-lifecycle", label: `Observe proven native Flow lifecycle: ${flowName}`, flowName, contractIds: [contract.id],
          evidence: (contract.evidence ?? []).map(entry => ({ contractId: contract.id, source: "native-contract-catalog", file: entry.source_path, line: entry.line_start, symbol: entry.symbol, sliceSha256: entry.slice_sha256 }))
        };
        mergeProbe(probeMap, probe);
        relatedProbeIds.push(probe.id);
      }
    }
    objectives.push({
      clauseId: clause.id, text: clause.text, concerns: clause.concerns, probeIds: [...new Set(relatedProbeIds)], contractIds: selectedContracts.map(item => item.contract.id),
      selectedRuntimeNodes: selectedNodes.map(item => ({ id: item.node.id, score: item.score, kind: item.node.kind, name: item.node.name })),
      status: relatedProbeIds.length ? "instrumented" : "manual-checkpoint",
      manualCheckpoint: relatedProbeIds.length ? null : `No safe automatic observer was proven for: ${clause.text}`
    });
  }
  return {
    schemaVersion: 1, tool: "Frame Conn Runtime Contract Probes", toolVersion: VERSION, id, goal, generatedAt: new Date().toISOString(),
    posture: "Observational and reversible. Unsupported runtime boundaries become manual checkpoints rather than guessed instrumentation.",
    nativeSystem: catalog.native_system ?? null, runtimeMap: { toolVersion: runtimeMap.toolVersion ?? null, sources: runtimeMap.sources ?? {}, nodeCount: runtimeMap.summary?.nodes ?? (runtimeMap.nodes ?? []).length, edgeCount: runtimeMap.summary?.edges ?? (runtimeMap.edges ?? []).length },
    clauseCoverage: corridor.clauseCoverage ?? null, objectives, probes: [...probeMap.values()].sort((a, b) => a.id.localeCompare(b.id))
  };
}

function renderHarness(manifest) {
  const data = JSON.stringify(manifest, null, 2);
  return `(() => {
  "use strict";
  const MANIFEST = ${data};
  const KEY = "FrameConnRuntimeProbe";
  if (window[KEY]?.active) window[KEY].stop();
  const state = { active: false, sequence: 0, events: [], cleanups: [], startedAt: null, stoppedAt: null };
  const safeClone = value => {
    try {
      if (value == null || ["string", "number", "boolean"].includes(typeof value)) return value;
      if (Array.isArray(value)) return value.slice(0, 8).map(safeClone);
      if (typeof value === "object") { const out = {}; for (const key of Object.keys(value).slice(0, 16)) if (typeof value[key] !== "function") out[key] = safeClone(value[key]); return out; }
      return String(value);
    } catch { return "[unserializable]"; }
  };
  const combatSnapshot = () => ({
    combatId: globalThis.game?.combat?.id ?? null, round: globalThis.game?.combat?.round ?? null, turn: globalThis.game?.combat?.turn ?? null, combatantId: globalThis.game?.combat?.combatant?.id ?? null,
    controlledTokenIds: (globalThis.canvas?.tokens?.controlled ?? []).map(token => token.id), targetIds: [...(globalThis.game?.user?.targets ?? [])].map(token => token.id)
  });
  const record = (probeId, kind, label, payload = {}) => {
    const entry = Object.freeze({ sequence: ++state.sequence, timestamp: new Date().toISOString(), probeId, kind, label, combat: combatSnapshot(), payload: safeClone(payload) });
    state.events.push(entry); console.log("[Frame Conn Probe]", entry); return entry;
  };
  const resolvePath = objectPath => objectPath.split(".").reduce((value, key) => value?.[key], globalThis);
  const installHook = probe => {
    if (!globalThis.Hooks?.on || !globalThis.Hooks?.off) return false;
    const handler = (...args) => record(probe.id, probe.kind, probe.label, { args });
    const hookId = Hooks.on(probe.hookName, handler); state.cleanups.push(() => Hooks.off(probe.hookName, hookId ?? handler)); return true;
  };
  const installFlow = probe => {
    if (!globalThis.Hooks?.on || !globalThis.Hooks?.off) return false;
    for (const phase of ["preFlow", "postFlow"]) {
      const hookName = "lancer." + phase + "." + probe.flowName;
      const handler = (...args) => record(probe.id, "flow-" + phase, probe.label + " [" + phase + "]", { hookName, args });
      const hookId = Hooks.on(hookName, handler); state.cleanups.push(() => Hooks.off(hookName, hookId ?? handler));
    }
    return true;
  };
  const installDomEvent = probe => {
    if (!globalThis.document?.addEventListener) return false;
    const handler = event => {
      const target = event.target; const matched = !probe.selector || Boolean(target?.matches?.(probe.selector) || target?.closest?.(probe.selector));
      if (matched) record(probe.id, probe.kind, probe.label, { eventType: event.type, selector: probe.selector, target: target?.outerHTML?.slice?.(0, 500) ?? target?.tagName ?? null });
    };
    document.addEventListener(probe.eventName, handler, true); state.cleanups.push(() => document.removeEventListener(probe.eventName, handler, true)); return true;
  };
  const installMethod = probe => {
    const owner = resolvePath(probe.objectPath); if (!owner || typeof owner[probe.methodName] !== "function") return false;
    const original = owner[probe.methodName];
    const wrapped = function(...args) {
      record(probe.id, probe.kind, probe.label, { phase: "call", args }); const result = original.apply(this, args);
      if (result && typeof result.then === "function") return result.then(value => { record(probe.id, probe.kind, probe.label, { phase: "resolve", result: value }); return value; }, error => { record(probe.id, probe.kind, probe.label, { phase: "reject", error: String(error) }); throw error; });
      record(probe.id, probe.kind, probe.label, { phase: "return", result }); return result;
    };
    owner[probe.methodName] = wrapped; state.cleanups.push(() => { if (owner[probe.methodName] === wrapped) owner[probe.methodName] = original; }); return true;
  };
  const installProbe = probe => { try {
    if (probe.kind === "hook") return installHook(probe); if (probe.kind === "flow-lifecycle") return installFlow(probe); if (probe.kind === "dom-event") return installDomEvent(probe); if (probe.kind === "global-method") return installMethod(probe); return false;
  } catch (error) { record(probe.id, "probe-install-error", probe.label, { error: String(error) }); return false; } };
  const api = {
    manifest: MANIFEST, get active() { return state.active; },
    start() { if (state.active) return api; state.active = true; state.startedAt = new Date().toISOString(); const installed = [], unavailable = []; for (const probe of MANIFEST.probes) (installProbe(probe) ? installed : unavailable).push(probe.id); record("probe-session", "session", "Probe session started", { installed, unavailable, goal: MANIFEST.goal }); return api; },
    mark(label, data = {}) { return record("manual-checkpoint", "manual", label, data); },
    snapshot(label = "snapshot", data = {}) { return record("state-snapshot", "snapshot", label, data); },
    evaluate() { const counts = new Map(); for (const event of state.events) counts.set(event.probeId, (counts.get(event.probeId) ?? 0) + 1); return MANIFEST.objectives.map(objective => { const observed = objective.probeIds.filter(id => (counts.get(id) ?? 0) > 0); return { clauseId: objective.clauseId, text: objective.text, status: objective.status, observedProbeIds: observed, result: objective.status === "manual-checkpoint" ? "MANUAL" : (observed.length ? "OBSERVED" : "NOT_OBSERVED") }; }); },
    report() { return Object.freeze({ schemaVersion: 1, probeId: MANIFEST.id, goal: MANIFEST.goal, startedAt: state.startedAt, stoppedAt: state.stoppedAt, active: state.active, evaluation: api.evaluate(), events: [...state.events] }); },
    clear() { state.events.length = 0; state.sequence = 0; return api; },
    stop() { if (!state.active) return api.report(); for (const cleanup of state.cleanups.splice(0).reverse()) { try { cleanup(); } catch (error) { console.warn("[Frame Conn Probe] cleanup failed", error); } } state.active = false; state.stoppedAt = new Date().toISOString(); record("probe-session", "cleanup", "Probe session stopped; instrumentation restored", {}); return api.report(); }
  };
  window[KEY] = api; api.start(); console.log("[Frame Conn Probe] Ready: .report(), .evaluate(), .mark(), .snapshot(), .stop()");
})();
`;
}

function renderChecklist(manifest) {
  const lines = [`# Runtime Probe Checklist — ${manifest.id}`, "", `**Goal:** ${manifest.goal}`, "", "## Run", "",
    "1. Open Foundry's browser developer console in the test world.",
    "2. Run `foundry-runtime-probe.js` with Frame Conn and Lancer enabled.",
    "3. Perform the player-facing behavior naturally; the probe does not trigger gameplay actions.",
    "4. Inspect `FrameConnRuntimeProbe.evaluate()` and `FrameConnRuntimeProbe.report()`.",
    "5. Use `.mark(label, data)` or `.snapshot(label, data)` for manual checkpoints.",
    "6. Call `.stop()` when finished so reversible wrappers/listeners are restored.", "", "## Behavioral obligations", ""];
  for (const objective of manifest.objectives) {
    lines.push(`- **${objective.clauseId} — ${objective.text}**`, `  - status: ${objective.status}`);
    if (objective.probeIds.length) lines.push(`  - probes: ${objective.probeIds.join(", ")}`);
    if (objective.contractIds.length) lines.push(`  - proven native contracts: ${objective.contractIds.join(", ")}`);
    if (objective.manualCheckpoint) lines.push(`  - manual checkpoint: ${objective.manualCheckpoint}`);
  }
  lines.push("", "## Interpretation", "", "`OBSERVED` means at least one source-backed observer associated with that clause fired. It is evidence of the runtime path, not by itself proof of every rule postcondition. `NOT_OBSERVED` means the expected observable boundary did not fire. `MANUAL` means the generator deliberately refused to guess an unsafe observer.", "");
  return lines.join("\n");
}

function writeBundle(manifest, outputDir) {
  fs.mkdirSync(outputDir, { recursive: true });
  const manifestPath = path.join(outputDir, "probe-manifest.json");
  const harnessPath = path.join(outputDir, "foundry-runtime-probe.js");
  const checklistPath = path.join(outputDir, "RUNTIME_TEST_CHECKLIST.md");
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + "\n", "utf8");
  fs.writeFileSync(harnessPath, renderHarness(manifest), "utf8");
  fs.writeFileSync(checklistPath, renderChecklist(manifest), "utf8");
  return { manifestPath, harnessPath, checklistPath };
}

function runSelfTest() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "frame-conn-runtime-probes-"));
  try {
    const corridor = { clauseCoverage: { complete: true, clauseCount: 3, coveredCount: 3, uncoveredClauses: [] }, clauses: [
      { id: "clause-1", text: "show the damage apply control", concerns: ["presentation"], complete: true },
      { id: "clause-2", text: "run DemoFlow and create chat output", concerns: ["native-execution"], complete: true },
      { id: "clause-3", text: "clear supplemental state after the turn", concerns: ["state", "lifecycle"], complete: true }
    ] };
    const runtimeMap = { toolVersion: "test", sources: { frameConn: { files: 1, fingerprint: "abc" } }, summary: { nodes: 4, edges: 0 }, nodes: [
      { id: "event:click", kind: "event", source: "frame-conn", name: "click .damage-apply", eventName: "click", selector: ".damage-apply", file: "demo.js", line: 1 },
      { id: "flow:DemoFlow", kind: "flow", source: "native-lancer", name: "DemoFlow", file: "flow.ts", line: 2 },
      { id: "hook:updateCombat", kind: "hook", source: "frame-conn", name: "updateCombat", file: "turn.js", line: 3 },
      { id: "effect:chat", kind: "effect", source: "native-lancer", name: "ChatMessage.create", effectKind: "chat", file: "flow.ts", line: 4 }
    ], edges: [] };
    const catalog = { native_system: { name: "foundryvtt-lancer", version: "test", git_commit: "abc" }, contracts: [{
      id: "native.flow.demo", status: "proven", contract_kind: "native-flow", title: "DemoFlow owns demo execution", summary: "DemoFlow creates chat output", keywords: ["demo", "chat"], boundary: { rule: "Native owns DemoFlow." }, evidence: [{ source_path: "flow.ts", symbol: "DemoFlow", line_start: 1, slice_sha256: "deadbeef" }]
    }] };
    const manifest = deriveManifest("show damage control, run DemoFlow chat, and clear state", "self-test", corridor, runtimeMap, catalog);
    if (manifest.objectives.length !== 3) throw new Error("self-test expected three clause objectives");
    for (const kind of ["dom-event", "flow-lifecycle", "hook", "global-method"]) if (!manifest.probes.some(probe => probe.kind === kind)) throw new Error(`self-test missing ${kind} probe`);
    const files = writeBundle(manifest, path.join(root, "bundle"));
    const syntax = spawnSync(process.execPath, ["--check", files.harnessPath], { encoding: "utf8" });
    if (syntax.status !== 0) throw new Error(`generated harness syntax invalid: ${syntax.stderr}`);
    const harness = fs.readFileSync(files.harnessPath, "utf8");
    for (const token of ["FrameConnRuntimeProbe", "evaluate()", "stop()", "cleanup"]) if (!harness.includes(token)) throw new Error(`self-test generated harness missing ${token}`);
    console.log("[runtime-contract-probes] Self-test passed.");
  } finally { fs.rmSync(root, { recursive: true, force: true }); }
}

function main() {
  const args = parseArgs(process.argv);
  if (args.selfTest) return runSelfTest();
  if (!args.goal?.trim()) throw new Error("--goal is required unless --self-test is used.");
  const goal = args.goal.trim(); const id = stableId(args.id ?? goal);
  const corridor = loadCorridor(goal, args.corridor);
  const runtimeMap = loadRuntimeMap(args.runtimeMap, args.nativeRoot);
  const catalog = loadCatalog(args.catalog);
  const manifest = deriveManifest(goal, id, corridor, runtimeMap, catalog);
  const outputDir = args.outputDir ?? path.join(DEFAULT_OUTPUT_ROOT, id);
  const files = writeBundle(manifest, outputDir);
  if (!args.jsonOnly) {
    const instrumented = manifest.objectives.filter(item => item.status === "instrumented").length;
    console.log(`Frame Conn Runtime Contract Probes ${VERSION}`);
    console.log(`goal=${goal}`); console.log(`clauses=${manifest.objectives.length} instrumented=${instrumented} manual=${manifest.objectives.length - instrumented}`); console.log(`probes=${manifest.probes.length}`);
    console.log(`manifest=${slash(path.relative(ROOT, files.manifestPath))}`); console.log(`foundry_harness=${slash(path.relative(ROOT, files.harnessPath))}`); console.log(`checklist=${slash(path.relative(ROOT, files.checklistPath))}`);
    for (const objective of manifest.objectives) { console.log(`  ${objective.clauseId} ${objective.status}: ${objective.text}`); for (const probeId of objective.probeIds) console.log(`    probe=${probeId}`); }
  }
}

try { main(); }
catch (error) { console.error(`[runtime-contract-probes] ${error instanceof Error ? error.message : String(error)}`); process.exit(1); }
